        for c in range(w - 1):
            if grid[r][c] == grid[r][c+1] == grid[r+1][c] == grid[r+1][c+1] != 0:
                corners = [(r-1,c-1), (r-1,c+2), (r+2,c-1), (r+2,c+2)]
                if not all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 0 for rr,cc in corners):
                    continue
                # Each outward ray receives the preceding corner's color in
                # clockwise corner order (NW, NE, SE, SW).
                nw, ne, sw, se = [grid[rr][cc] for rr,cc in corners]
                colors = [sw, nw, ne, se]
                dirs = [(-1,-1), (-1,1), (1,1), (1,-1)]
                for (rr,cc), color, (dr,dc) in zip(corners, colors, dirs):
                    while 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
